package com.termux.app.workspace;
import org.json.*;
import java.util.*;
/** Synthetic metadata only; no chat or generated text enters this report. */
final class LocalAiBenchmark {
 String model="",backend="",state="idle",error="";int mode;boolean running,stopRequested;final ArrayList<JSONObject> batches=new ArrayList<>(),results=new ArrayList<>();JSONObject current;
 synchronized void begin(String model,String backend,int mode){if(mode<0||mode>2)throw new IllegalArgumentException("Invalid benchmark mode");this.model=model;this.backend=backend;this.mode=mode;state="running";error="";running=true;stopRequested=false;current=null;batches.clear();results.clear();}
 synchronized void accept(String json){if(!running)return;try{JSONObject p=new JSONObject(json);int trial=p.getInt("trial"),trials=p.getInt("trials"),input=p.getInt("input"),done=p.getInt("processed"),count=p.getInt("count");if(trial<1||trial>trials||trials>8||input<1||input>4096||done<0||done>input||count<0||count>512||p.getInt("threads")<1||p.getInt("threads")>8||p.getLong("decodeNs")<0||p.getLong("cpuNs")<0||p.getLong("batchNs")<0||p.getLong("batchCpuNs")<0||p.getLong("elapsedNs")<0||p.getInt("context")<input||!Arrays.asList(256,512).contains(p.getInt("batch"))||p.getInt("ubatch")!=p.getInt("batch")/2||p.getBoolean("complete")!=(done==input))return;current=p;if(count>0){if(batches.size()<256)batches.add(p);if(p.getBoolean("complete")&&results.stream().noneMatch(r->r.optInt("trial")==trial))results.add(p);}}catch(Exception ignored){}}
 synchronized void requestStop(){if(running)stopRequested=true;}
 synchronized void finish(String state,String category){this.state=state;error=category!=null&&category.matches("[A-Za-z0-9_$]{1,90}")?category:"";running=false;}
 static String name(int mode,boolean ru){return mode==1?(ru?"Сравнение потоков 2/4/6/8":"Thread comparison 2/4/6/8"):mode==2?(ru?"Сравнение порций 256/128 и 512/256":"Batch comparison 256/128 and 512/256"):(ru?"Длина входа 512/1024/2048/4096":"Input length 512/1024/2048/4096");}
 static String ms(long n){return String.format(Locale.ROOT,"%.2f",n/1000000.0);}
 static String rate(JSONObject p){return p.optLong("decodeNs")<=0?"—":String.format(Locale.ROOT,"%.1f",p.optInt("processed")*1e9/p.optLong("decodeNs"));}
 synchronized String summary(boolean ru){StringBuilder s=new StringBuilder("Termux Job’s "+com.termux.BuildConfig.VERSION_NAME+" · CPU prefill test\n");s.append(ru?"Модель: ":"Model: ").append(model).append("\n").append(ru?"Движок: ":"Engine: ").append(backend).append("\n").append(name(mode,ru)).append("\n").append(ru?"Состояние: ":"State: ").append(running?(stopRequested?(ru?"остановка после текущей порции":"stopping after current batch"):(ru?"выполняется":"running")):state.equals("completed")?(ru?"завершён":"completed"):state.equals("stopped")?(ru?"остановлен":"stopped"):state.equals("failed")?(ru?"ошибка":"failed"):(ru?"не запущен":"not started")).append("\n");
 if(current!=null)s.append(ru?"Прогон / обработано: ":"Trial / processed: ").append(current.optInt("trial")).append("/").append(current.optInt("trials")).append(" · ").append(current.optInt("processed")).append("/").append(current.optInt("input")).append("\n");
 s.append(ru?"Синтетические токены; без истории, инструментов, генерации и кэша. Два прохода в прямом/обратном порядке.\n":"Synthetic tokens; no history, tools, generation or cache. Two forward/reverse passes.\n");
 for(JSONObject p:results)s.append("#").append(p.optInt("trial")).append(" ").append(p.optInt("input")).append(ru?" ток. · потоки ":" tok · threads ").append(p.optInt("threads")).append(" · batch/ubatch ").append(p.optInt("batch")).append("/").append(p.optInt("ubatch")).append(" · context ").append(p.optInt("context")).append("\n").append(ru?"Декодирование / весь прогон / CPU процесса (мс): ":"Decode / trial elapsed / process CPU (ms): ").append(ms(p.optLong("decodeNs"))).append(" / ").append(ms(p.optLong("elapsedNs"))).append(" / ").append(ms(p.optLong("cpuNs"))).append(" · ").append(rate(p)).append(" tok/s\n");
 if(!error.isEmpty())s.append(ru?"Категория ошибки: ":"Error category: ").append(error).append("\n");
 return s.append(ru?"CPU-время суммируется по потокам процесса и может быть больше реального времени. Это не загрузка всего устройства. Создание временного контекста исключено из замера.\n":"Process CPU time sums threads and can exceed wall time; it is not whole-device usage. Temporary context creation is outside the measured interval.\n").toString();}
 synchronized String events(boolean ru){StringBuilder s=new StringBuilder();for(JSONObject p:batches)s.append("#").append(p.optInt("trial")).append(" ").append(p.optInt("processed")).append("/").append(p.optInt("input")).append(" · ").append(p.optInt("count")).append(ru?" ток. · декодирование/CPU (мс): ":" tok · decode/CPU (ms): ").append(ms(p.optLong("batchNs"))).append("/").append(ms(p.optLong("batchCpuNs"))).append("\n");return s.toString();}
 synchronized String report(boolean ru){return summary(ru)+"\n"+events(ru);}
}
